  .srv-icon.b5{background:linear-gradient(135deg,#FF9933,#FFB347);}
  .srv-icon.b6{background:linear-gradient(135deg,#8e44ad,#9b59b6);}
  .srv-icon.b7{background:linear-gradient(135deg,#16a085,#1abc9c);}
