  .srv-num { position:absolute; top:14px; right:16px; font-family:'Syne',sans-serif; font-size:26px; font-weight:800; color:rgba(255,255,255,0.04); }

  /* ══════════════════════════════════════════════════
     PAGE 4 – WHY CHOOSE US
  ══════════════════════════════════════════════════ */
  .why { background: linear-gradient(160deg, #060f22 0%, #0b1d3f 60%, #10213a 100%); }
  .why-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:44px; }
