  .compare-banner { margin-top:36px; background:linear-gradient(135deg,rgba(255,153,51,0.15),rgba(19,136,8,0.1),rgba(19,71,180,0.15)); border:1px solid rgba(255,153,51,0.3); border-radius:18px; padding:26px 32px; display:flex; align-items:center; gap:20px; }
