  .usp-badge { display:inline-block; background:linear-gradient(135deg,rgba(255,153,51,0.2),rgba(19,136,8,0.15)); border:1px solid rgba(255,153,51,0.4); border-radius:6px; padding:9px 26px; font-size:11px; font-weight:700; letter-spacing:2px; text-transform:uppercase; margin-bottom:28px; color:var(--saffron); }
