  .trust-sep { width:1px; background:rgba(255,255,255,0.1); }

  /* ══════════════════════════════════════════════════
     PAGE 7 – BENEFITS
  ══════════════════════════════════════════════════ */
  .benefits { background: linear-gradient(180deg, #060e1f 0%, #0b1933 100%); }
  .benefits-visual { display:grid; grid-template-columns:1fr 1fr; gap:36px; margin-top:44px; align-items:start; }
  .benefit-item { display:flex; gap:16px; margin-bottom:24px; }
  .benefit-step { width:48px;height:48px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-family:'Syne',sans-serif;font-size:16px;font-weight:800;background:rgba(255,153,51,0.1);border:2px solid rgba(255,153,51,0.35);color:var(--saffron); }
  .benefit-body h4 { font-family:'Syne',sans-serif; font-size:15px; font-weight:700; margin-bottom:5px; }
