  .benefit-bar { height:100%; border-radius:2px; background:linear-gradient(90deg,var(--saffron),var(--green-india)); }
  .score-board { background:rgba(255,255,255,0.03); border:1px solid rgba(255,153,51,0.18); border-radius:18px; padding:28px; text-align:center; }
