  .cta-sites { display:flex; gap:18px; justify-content:center; flex-wrap:wrap; margin-bottom:40px; }
  .site-pill { display:flex;align-items:center;gap:10px; background:linear-gradient(135deg,rgba(255,153,51,0.15),rgba(19,136,8,0.1),rgba(19,71,180,0.15)); border:1px solid rgba(255,153,51,0.35); border-radius:8px; padding:13px 28px; font-family:'Syne',sans-serif; font-size:15px; font-weight:700; }
  .cta-tagline { font-size:12px; color:rgba(255,255,255,0.25); letter-spacing:2px; text-transform:uppercase; }
  .brand-strip { margin-top:40px; background:linear-gradient(90deg,rgba(255,153,51,0.15),rgba(19,136,8,0.1),rgba(19,71,180,0.15)); border:1px solid rgba(255,153,51,0.25); border-radius:14px; padding:18px 36px; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; }

  /* ─── PAGE NUMBER ────────────────────────────────── */
  .pgnum { position:absolute; bottom:28px; right:38px; font-family:'Syne',sans-serif; font-size:11px; color:rgba(255,255,255,0.18); letter-spacing:2px; z-index:10; }

